import { readFile, writeFile } from 'node:fs/promises';

const header = '// Generated by scripts/build-bundle.mjs. Edit src/roulette.js or src/main.js, then run npm run build:bundle.\n\n';

function stripModuleSyntax(source, kind) {
  let output = source;

  if (kind === 'main') {
    output = output.replace(/^import\s*\{[\s\S]*?\}\s*from\s*['"]\.\/roulette\.js['"];\s*/m, '');
  }

  output = output
    .replace(/^export\s+const\s+/gm, 'const ')
    .replace(/^export\s+function\s+/gm, 'function ')
    .replace(/^export\s+\{[\s\S]*?\};\s*/gm, '');

  return output.trim();
}

const rouletteSource = await readFile(new URL('../src/roulette.js', import.meta.url), 'utf8');
const mainSource = await readFile(new URL('../src/main.js', import.meta.url), 'utf8');

const bundle = [
  header,
  stripModuleSyntax(rouletteSource, 'roulette'),
  '',
  stripModuleSyntax(mainSource, 'main'),
  '',
].join('\n');

await writeFile(new URL('../src/app.bundle.js', import.meta.url), bundle, 'utf8');
console.log('Built src/app.bundle.js');
